"""Make It Yours: keep a design for later by saving it as its own portfolio, without touching the current one."""
from playwright.sync_api import sync_playwright
from h import *
with sync_playwright() as p:
    b = p.chromium.launch(); c = b.new_context(viewport={'width': 1400, 'height': 900}); pg = c.new_page()
    to_editor(pg, 1, 'Professional', 'Original')
    pg.evaluate("PV.editPath('person/name','Aryan Singh')"); pg.wait_for_timeout(900)
    d0 = pg.evaluate("JSON.stringify(PV.S.project.design)"); name0 = pg.evaluate("PV.S.project.name"); n0 = pg.evaluate("PV.S.index.length"); content0 = pg.evaluate("JSON.stringify([PV.S.project.person,PV.S.project.sections])")
    pg.click('.miybtn'); pg.click('.preset:has-text("Bold")'); pg.wait_for_timeout(1500)
    ok('three variations offered', pg.evaluate('PV.S.variations.length') == 3)
    vd = pg.evaluate("JSON.stringify(PV.S.variations.find(v=>v.id===PV.S.activeVar).design)"); vl = pg.evaluate("PV.S.variations.find(v=>v.id===PV.S.activeVar).label")
    pg.click('[data-act=miysave]'); pg.wait_for_timeout(1200)
    ok('save adds exactly one new portfolio', pg.evaluate('PV.S.index.length') == n0 + 1, pg.evaluate('PV.S.index.length'))
    ok('toast tells where to find it', 'All portfolios' in ' '.join(pg.locator('.toast').all_inner_texts()))
    ok('current portfolio unchanged (design, name, content)', pg.evaluate("JSON.stringify(PV.S.project.design)") == d0 and pg.evaluate("PV.S.project.name") == name0 and pg.evaluate("JSON.stringify([PV.S.project.person,PV.S.project.sections])") == content0)
    ok('still previewing variations (nothing applied)', pg.evaluate('PV.S.variations.length') == 3 and pg.evaluate('PV.S.activeVar') is not None)
    pg.evaluate("PV.ACT.miydiscard()"); pg.wait_for_timeout(300)
    pg.evaluate("PV.Router.go('/projects')"); pg.wait_for_timeout(1000)
    names = pg.evaluate("PV.S.index.map(x=>x.name)"); ok('listed in My portfolios with variation name', any(vl in n for n in names), names)
    pg.reload(); pg.wait_for_timeout(1500); ok('survives refresh', pg.evaluate("PV.S.index.length") == n0 + 1)
    pg.evaluate("PV.ACT.openproj({dataset:{id:PV.S.index.find(x=>x.name.includes(%r)).id}})" % vl); pg.wait_for_timeout(1800)
    ok('opening it shows the saved design with the same content', pg.evaluate("JSON.stringify(PV.S.project.design)") == vd and pg.evaluate("JSON.stringify([PV.S.project.person,PV.S.project.sections])") == content0 and fr(pg).locator('.name').inner_text().lower() == 'aryan singh')
    pg.evaluate("PV.editPath('person/title','Edited only in the copy')"); pg.wait_for_timeout(1200)
    orig = pg.evaluate("PV.S.index.find(x=>x.name==%r).id" % name0); pg.evaluate("PV.ACT.openproj({dataset:{id:%r}})" % orig); pg.wait_for_timeout(1500)
    ok('copy is independent: original not affected by edits to the copy', pg.evaluate("PV.S.project.person.title") != 'Edited only in the copy')
    pg.click('.miybtn'); pg.click('.preset:has-text("Minimal")'); pg.wait_for_timeout(1500); n1 = pg.evaluate('PV.S.index.length')
    pg.click('[data-act=miysaveall]'); pg.wait_for_timeout(2000); ok('"Save all" stores every option (3 more portfolios)', pg.evaluate('PV.S.index.length') == n1 + 3, pg.evaluate('PV.S.index.length') - n1)
    b.close()
bad = [r for r in res if not r[1]]; print(len(res) - len(bad), 'passed', len(bad), 'failed')
